/* eslint-disable-next-line @typescript-eslint/no-unused-vars */
namespace Innovasys.Content.Features {

    export class TopicsDocumentFeature extends DocumentFeatureBase implements IDocumentFeature {

        public getName(): string {
            return "topics";
        }

        public populateResponsiveConfiguration(configuration: ResponsiveConfiguration): void {
            super.populateResponsiveConfiguration(configuration);
            if (configuration.profileName === "mobile" || configuration.profileName === "tablet") {
                switch (configuration.profileName) {
                    case "tablet":
                        break;
                    case "mobile":
                        configuration.clickTargets.push(
                            new ResponsiveClickTarget(".i-glossary-letter-header", ResponsiveClickTargetKind.block));
                        break;
                    // No default
                }
                // Common mobile and tablet
            }
        }

        public applyResponsiveConfiguration(configuration: ResponsiveConfiguration): void {
            // Remove slimbox click handler in responsive mode
            if (configuration.profileName === "mobile") {
                $(".i-glossary-letter-header")
                    .addClass("i-section-heading")
                    .next()
                    .addClass("i-section-content");
            }
        }

    }

    export class TopicsDocumentFeatureFactory {

        public createInstance(documentInstance: Document): IDocumentFeature {
            // Always enabled
            return new TopicsDocumentFeature(documentInstance);
        }

    }

}

Innovasys.Content.DocumentFeatureConfiguration.registerDocumentFeatureFactory(
    new Innovasys.Content.Features.TopicsDocumentFeatureFactory());
