/* eslint-disable-next-line @typescript-eslint/no-unused-vars */
namespace Innovasys.Content.Features {

    const highlightTextConstants = {
        textNodeType: 3,
        elementNodeType: 1
    };

    export class HighlightTextDocumentFeature extends DocumentFeatureBase implements IDocumentFeature {

        // Stores the first found match so we can scroll to it
        private _firstMatch: HTMLElement = null;


        /**
         * Merge any adjacent text nodes (left behind from search highlight)
         * @param parentNode The node to start searching from.
         */
        private static cleanUpTextNodes(parentNode: Node): void {

            let node: Node;
            let lastNode: Node;
            let mergeCount: number;

            do {
                mergeCount = 0;
                for (let x = 1; x < parentNode.childNodes.length; x++) {
                    node = parentNode.childNodes[x];
                    lastNode = node.previousSibling;

                    if (node.nodeType === highlightTextConstants.textNodeType
                        && lastNode.nodeType === highlightTextConstants.textNodeType) {

                        node.nodeValue = lastNode.nodeValue + node.nodeValue;
                        parentNode.removeChild(lastNode);
                        mergeCount++;
                    }
                }
            } while (mergeCount > 0);

            /* eslint-disable-next-line @typescript-eslint/prefer-for-of */
            for (let x = 0; x < parentNode.childNodes.length; x++) {
                HighlightTextDocumentFeature.cleanUpTextNodes(parentNode.childNodes[x]);
            }

        }

        public getName(): string {
            return "Highlight Text";
        }

        public onMessage(message: WindowMessage): void {
            if (message != null) {
                switch (message.messageType) {
                    case DocumentMessageNames.quickSearch:
                        this.highlightText(message.messageData);
                        break;
                    case DocumentMessageNames.resetQuickSearch:
                        this.removeAllHighlights();
                        break;
                    case DocumentMessageNames.searchHighlightComplete:
                        this.searchHighlightComplete();
                        break;
                    // No default
                }
            }
        }

        private highlightText(text: string) {
            const rootElement: HTMLElement = this.documentInstance.rootElement;

            if (text !== "") {
                this.highlightTextInElement(rootElement, text);
            }
        }

        public initializeContent(rootSelector: JQuery, isInitialLoad: boolean = false): void {
            if (isInitialLoad) {
                const location = Browser.getLocationInfo();

                if (location.search) {
                    const prefix = "?highlight=";

                    if (location.search.indexOf(prefix) === 0) {
                        const keywords = decodeURIComponent(location.search.substring(prefix.length)).split(",");

                        this.removeAllHighlights();

                        for (const keyword of keywords) {
                            if (keyword != null && keyword !== "") {
                                this.highlightText(keyword);
                            }
                        }

                        this.searchHighlightComplete();
                    }
                }
            }
        }

        private searchHighlightComplete() {
            // Scroll to the first hit if it's not already visible
            if (this._firstMatch != null) {
                const rootElement: HTMLElement = this.documentInstance.rootElement;
                const ownerDocument: HTMLDocument = (rootElement.ownerDocument) as HTMLDocument;
                if (DomHelpers.getElementPosition(this._firstMatch).top > ownerDocument.documentElement.scrollTop
                    + ownerDocument.documentElement.clientHeight
                    || DomHelpers.getElementPosition(this._firstMatch).top < ownerDocument.documentElement.scrollTop) {

                    ownerDocument.documentElement.scrollTop = this._firstMatch.offsetTop;
                }
            }
            this._firstMatch = null;
        }

        /**
         * Finds some specific text and wraps with a search result highlight element.
         * @param element The root element to search through.
         * @param text The text to find.
         */
        public highlightTextInElement(element: HTMLElement, text: string): void {

            let node: Node;
            let nodeText: string;
            let lowerCaseNodeText: string;
            let highlightSpan: HTMLSpanElement;
            let remainingText: Node;
            const ownerDocument: HTMLDocument = (element.ownerDocument) as HTMLDocument;

            const textRegExp = new RegExp(`(^|[\\b\\s]|[^\\w])(${this.escapeForRegExp(text)})(?=$|[\\b\\s]|[^\\w])`, "i");

            // Traverse the document backwards otherwise the DOM returns stale objects as
            //  we make modifications
            for (let x: number = element.childNodes.length - 1; x >= 0; x--) {

                node = element.childNodes[x];

                let checkedElementVisible = false;

                // Text Node
                if (node.nodeType === highlightTextConstants.textNodeType) {

                    nodeText = node.nodeValue;
                    lowerCaseNodeText = nodeText.toLowerCase();

                    let match: RegExpMatchArray;
                    const newNodes: Node[] = [];

                    while (nodeText.length > 0 && (match = lowerCaseNodeText.match(textRegExp)) !== null) {

                        const pos = match.index + match[1].length;

                        if (pos > 0) {
                            // Text up to match
                            newNodes.push(ownerDocument.createTextNode(nodeText.substring(0, pos)));
                        }

                        // Match highlight
                        highlightSpan = (ownerDocument.createElement("SPAN") as HTMLSpanElement);
                        highlightSpan.className = "i-search-highlight";
                        highlightSpan.appendChild(ownerDocument.createTextNode(nodeText.substring(pos, pos + text.length)));
                        newNodes.push(highlightSpan);

                        // Remainder
                        nodeText = nodeText.substring(pos + text.length);
                        lowerCaseNodeText = nodeText.toLowerCase();

                        // Store the first (last)hit so we can scroll to it
                        this._firstMatch = highlightSpan;

                        if (!checkedElementVisible) {
                            // Delegate responsibility to the document and features
                            this.documentInstance.ensureElementVisible(node.parentElement);

                            checkedElementVisible = true;
                        }
                    }

                    if (newNodes.length > 0) {
                        if (nodeText.length > 0) {
                            // Remainder after the last match
                            newNodes.push(ownerDocument.createTextNode(nodeText));
                        }

                        for (const newNode of newNodes) {
                            node.parentNode.insertBefore(newNode, node);
                            if (this._firstMatch != null && node.nodeType === highlightTextConstants.elementNodeType) {
                                this._firstMatch = node as HTMLSpanElement;
                            }
                        }

                        node.parentNode.removeChild(node);
                    }

                } else if (node.nodeType === highlightTextConstants.elementNodeType) {
                    // Element node

                    const elementNode: HTMLElement = node as HTMLElement;
                    // To ensure we don't modify script or go over
                    //  highlights we have already applied
                    if (elementNode.nodeName !== "SCRIPT"
                        && !(elementNode.nodeName === "SPAN" && elementNode.className === "i-search-highlight")) {

                        this.highlightTextInElement(elementNode, text);
                    }
                }
            }
        }

        /**
         * Returns any search highlight spans in this document.
         */
        private getHighlightSpans(): JQuery {
            return this.documentInstance.rootSelector.find(".i-search-highlight");
        }

        /**
         * Remove any search highlight spans.
         */
        private removeAllHighlights(): void {

            const spans: JQuery = this.getHighlightSpans();
            spans.each((index: number, element: Element) => {
                const span: JQuery<Element> = $(element);
                span.replaceWith(span.html());
            });

            // This process may have resulted in multiple contiguous text nodes
            //  which could cause problems with subsequent search highlight operations
            // So we join any continguous text nodes here
            HighlightTextDocumentFeature.cleanUpTextNodes(this.documentInstance.rootElement);

            $("#i-remove-highlighting").hide();

        }

        private escapeForRegExp(source: string): string {
            return source.replace(/[-/\\^$*+?.()|[\]{}]/g, "\\$&");
        }

    }

    export class HighlightTextDocumentFeatureFactory {

        public createInstance(documentInstance: Document): IDocumentFeature {
            // Always enabled
            return new HighlightTextDocumentFeature(documentInstance);
        }

    }

}

Innovasys.Content.DocumentFeatureConfiguration.registerDocumentFeatureFactory(
    new Innovasys.Content.Features.HighlightTextDocumentFeatureFactory());
