/* eslint-disable-next-line @typescript-eslint/no-unused-vars */
namespace Innovasys.Content {

    export class DomHelpers {

        /**
         * Returns an elements absolute position, allowing for the non-scrolling header
         * @param element The element to find the absolute position of
         */
        public static getElementPosition(element: HTMLElement): ElementPosition {
            let offsetLeft = 0;
            let offsetTop = 0;

            while (element) {
                const MSIE_4_VERSION = 4;
                // Allow for the scrolling body region in IE
                if (Browser.msIeVersion() > MSIE_4_VERSION) {
                    offsetLeft += (element.offsetLeft - element.scrollLeft);
                    offsetTop += (element.offsetTop - element.scrollTop);
                } else {
                    offsetLeft += element.offsetLeft;
                    offsetTop += element.offsetTop;
                }

                element = (element.offsetParent as HTMLElement);
            }

            /* eslint-disable-next-line @typescript-eslint/no-explicit-any */
            const leftMargin = (document.body as any).leftMargin as number;
            if (BrowserInfo.getUserAgent().indexOf("Mac") !== -1
                && typeof leftMargin !== "undefined") {

                offsetLeft += leftMargin;
                /* eslint-disable-next-line @typescript-eslint/no-explicit-any */
                offsetTop += ((document.body as any).topMargin as number);
            }

            return new ElementPosition(offsetLeft, offsetTop);
        }

        /**
         * Returns the text from the containing table. Uses this as the context element from which to find the containing table.
         */
        public static getTextFromContainingTable(element: HTMLElement): string {
            const parentTableQuery = $(element)
                .parents("table")
                .get(0);
            const parentTable: JQuery = $(parentTableQuery);
            const tableCell: HTMLTableCellElement = parentTable.find("td").get(0) as HTMLTableCellElement;
            if (tableCell != null) {
                if (tableCell.textContent != null) {
                    return tableCell.textContent;
                } else if (tableCell.innerText != null) {
                    return tableCell.innerText;
                } else {
                    return $(tableCell).text();
                }
            }
        }

    }

}
